/*
 * [演算法說明]
 * 這是一個線性丟番圖方程 (Linear Diophantine Equation) 的應用問題。
 * 需要找到非負整數 x, y 滿足 n1*x + n2*y = n，並使 c1*x + c2*y 最小。
 * 
 * 步驟：
 * 1. 使用擴展歐幾里得演算法 (Extended Euclidean Algorithm) 找到 n1*x + n2*y = gcd(n1, n2) 的一組整數解 x0, y0。
 * 2. 如果 n 不能被 gcd(n1, n2) 整除，則無解，輸出 "failed"。
 * 3. 得到通解：
 *    x = (x0 * n / g) + k * (n2 / g)
 *    y = (y0 * n / g) - k * (n1 / g)
 * 4. 由於需要 x >= 0 且 y >= 0，可以確定 k 的取值範圍 [k_min, k_max]。
 * 5. 代入邊界的 k 值，比較並選取使成本 c1*x + c2*y 最小的解。
 */

#include <iostream>
#include <cmath>
#include <algorithm>

using namespace std;

typedef long long ll;

ll extended_gcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) {
        x = 1; y = 0;
        return a;
    }
    ll x1, y1;
    ll d = extended_gcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - y1 * (a / b);
    return d;
}

int main() {
    ll n;
    while (cin >> n && n != 0) {
        ll c1, n1, c2, n2;
        cin >> c1 >> n1 >> c2 >> n2;

        ll x, y;
        ll g = extended_gcd(n1, n2, x, y);

        if (n % g != 0) {
            cout << "failed" << endl;
            continue;
        }

        ll k_min = ceil(-(double)x * n / n2);
        ll k_max = floor((double)y * n / n1);

        if (k_min > k_max) {
            cout << "failed" << endl;
        } else {
            ll x1 = (x * n / g) + k_min * (n2 / g);
            ll y1 = (y * n / g) - k_min * (n2 / g);
            ll x2 = (x * n / g) + k_max * (n2 / g);
            ll y2 = (y * n / g) - k_max * (n2 / g);

            if (c1 * x1 + c2 * y1 <= c1 * x2 + c2 * y2) {
                cout << x1 << " " << y1 << endl;
            } else {
                cout << x2 << " " << y2 << endl;
            }
        }
    }
    return 0;
}
